import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triu_mm_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                   const float* __restrict__ B,
                                   float* __restrict__ C,
                                   int N) {
    const int row = blockIdx.y * blockDim.y + threadIdx.y;
    const int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row >= N || col >= N || row > col) return;

    float sum = 0.0f;
    for (int k = row; k <= col; ++k) {
        sum += A[row * N + k] * B[k * N + col];
    }
    C[row * N + col] = sum;
}

torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int BLOCK_SIZE = 16;
    dim3 blocks((N + BLOCK_SIZE - 1) / BLOCK_SIZE,
                (N + BLOCK_SIZE - 1) / BLOCK_SIZE);
    dim3 threads(BLOCK_SIZE, BLOCK_SIZE);

    triu_matmul_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

triu_mm_cpp = "torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);"

triu_mm = load_inline(
    name="triu_mm",
    cpp_sources=triu_mm_cpp,
    cuda_sources=triu_mm_source,
    functions=["triu_matmul_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.custom_matmul = triu_mm

    def forward(self, A, B):
        return self.custom_matmul.triu_matmul_cuda(A, B)
